1	import { createServer } from 'node:http';
2	import type { IncomingMessage, ServerResponse } from 'node:http';
3	import { mkdirSync, readFileSync, renameSync, rmSync, writeFileSync } from 'node:fs';
4	import { randomUUID } from 'node:crypto';
5	import { join } from 'node:path';
6	
7	const PRODUCT: string = 'QuillPress';
8	const RESOURCE: string = 'articles';
9	const MAX_BODY_BYTES: number = 5 * 1024 * 1024;
10	const PAGE: string = `<!doctype html>
11	<html lang="zh-CN">
12	<meta charset="utf-8">
13	<meta name="viewport" content="width=device-width,initial-scale=1">
14	<title>QuillPress · 内容编辑与刊物发布</title>
15	<style>
16	body{font-family:system-ui,sans-serif;max-width:52rem;margin:3rem auto;padding:0 1rem;line-height:1.7;color:#1f2328}
17	a{color:#175b9c}
18	h2{margin-top:2rem}
19	form{border:1px solid #d0d7de;border-radius:8px;padding:1rem 1.25rem;margin:1rem 0 1.5rem}
20	form.editing{border-color:#175b9c;box-shadow:0 0 0 2px rgba(23,91,156,.15)}
21	label{display:block;font-weight:600;margin:.9rem 0 .3rem}
22	input[type=text],textarea{width:100%;box-sizing:border-box;font:inherit;padding:.5rem .6rem;border:1px solid #d0d7de;border-radius:6px;background:#fff;color:inherit}
23	textarea{resize:vertical}
24	button{margin-top:1.1rem;font:inherit;padding:.5rem 1.3rem;border-radius:6px;border:1px solid #175b9c;background:#175b9c;color:#fff;cursor:pointer}
25	button.secondary{background:#fff;color:#175b9c;margin-left:.6rem}
26	button:disabled{opacity:.55;cursor:default}
27	button.danger{border-color:#c0392b;background:#fff;color:#c0392b}
28	.status{margin:.8rem 0 0;min-height:1.4em}
29	.status.ok{color:#1a7f37}.status.err{color:#c0392b}.status.warn{color:#8a5a00}
30	.edit-banner{margin:0 0 .25rem;padding:.6rem .8rem;border-radius:6px;background:#eef4fb;border:1px solid #b6d2ee;color:#14467a;font-size:.92rem}
31	.edit-banner code{background:#dde9f6;padding:0 .3rem;border-radius:3px}
32	.edit-banner .meta{color:#3d6391;font-size:.85rem;margin-top:.2rem}
33	ul.articles{list-style:none;padding:0;margin:0}
34	article.draft{border:1px solid #d0d7de;border-radius:8px;padding:1rem 1.25rem;margin:1rem 0}
35	article.draft.editing{border-color:#175b9c;box-shadow:0 0 0 2px rgba(23,91,156,.15)}
36	.draft h3{margin:0 0 .4rem;word-break:break-word}
37	.draft .meta{color:#656d76;font-size:.85rem;margin:0 0 .5rem}
38	.draft .summary{white-space:pre-wrap;word-break:break-word;margin:0 0 .4rem;color:#3a4149}
39	.draft .actions{margin:.6rem 0 0}
40	.draft .actions button{margin:0;padding:.3rem .9rem;font-size:.88rem}
41	.draft .editing-tag{margin-left:.5rem;font-size:.78rem;font-weight:600;color:#175b9c;border:1px solid #175b9c;border-radius:999px;padding:0 .55rem;vertical-align:middle}
42	.empty{color:#656d76}
43	.empty.err{color:#c0392b}
44	.conflict{margin-top:1rem;border:1px solid #d9a441;border-radius:8px;background:#fffaf0;padding:1rem 1.25rem}
45	.conflict h3{margin:0 0 .3rem;color:#8a5a00;font-size:1.05rem}
46	.conflict .conflict-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-top:.7rem}
47	@media (max-width:46rem){.conflict .conflict-grid{grid-template-columns:1fr}}
48	.conflict .ver{border:1px solid #d0d7de;border-radius:6px;padding:.7rem .85rem;background:#fff;min-width:0}
49	.conflict .ver.saved{border-color:#8ab46a;background:#f6fbf2}
50	.conflict .ver h4{margin:0 0 .5rem;font-size:.92rem}
51	.conflict .ver dl{margin:0}
52	.conflict .ver dt{font-weight:600;font-size:.82rem;color:#57606a;margin-top:.5rem}
53	.conflict .ver dt:first-child{margin-top:0}
54	.conflict .ver dd{margin:.15rem 0 0;white-space:pre-wrap;word-break:break-word;font-size:.88rem;background:#f6f8fa;border-radius:4px;padding:.35rem .5rem;max-height:12rem;overflow:auto}
55	.conflict .ver.saved dd{background:#eef5e8}
56	.conflict .ver dd.empty-field{color:#8a8f98;font-style:italic;background:transparent;padding:0}
57	.conflict .actions{margin-top:.8rem}
58	.conflict .actions button{margin-top:0}
59	.conflict .actions .tip{font-size:.82rem;color:#8a5a00;margin-left:.6rem}
60	</style>
61	<main>
62	<h1>QuillPress</h1>
63	<p>内容编辑与刊物发布</p>
64	
65	<section aria-labelledby="compose-heading">
66	<h2 id="compose-heading">保存草稿</h2>
67	<form id="draft-form" autocomplete="off">
68	  <div id="edit-banner" class="edit-banner" hidden></div>
69	  <label for="title">标题</label>
70	  <input id="title" name="title" type="text">
71	  <label for="summary">摘要（可选）</label>
72	  <textarea id="summary" name="summary" rows="3"></textarea>
73	  <label for="body">正文</label>
74	  <textarea id="body" name="body" rows="10"></textarea>
75	  <button id="save-btn" type="submit">保存草稿</button>
76	  <button id="cancel-btn" class="secondary" type="button" hidden>取消编辑</button>
77	  <p id="status" class="status" role="status" aria-live="polite"></p>
78	  <div id="conflict-box" class="conflict" hidden></div>
79	</form>
80	</section>
81	
82	<section aria-labelledby="list-heading">
83	<h2 id="list-heading">草稿列表</h2>
84	<ul id="article-list" class="articles" aria-busy="true"></ul>
85	<p id="list-notice" class="empty err" role="status" aria-live="polite" hidden></p>
86	<p id="empty-tip" class="empty">草稿加载中…</p>
87	</section>
88	
89	<p><a href="/api/articles">查看文章列表接口</a> · <a href="/health">服务状态</a></p>
90	</main>
91	<script>
92	(function () {
93	  'use strict';
94	  var form = document.getElementById('draft-form');
95	  var titleInput = document.getElementById('title');
96	  var summaryInput = document.getElementById('summary');
97	  var bodyInput = document.getElementById('body');
98	  var saveBtn = document.getElementById('save-btn');
99	  var cancelBtn = document.getElementById('cancel-btn');
100	  var statusEl = document.getElementById('status');
101	  var editBanner = document.getElementById('edit-banner');
102	  var conflictBox = document.getElementById('conflict-box');
103	  var listEl = document.getElementById('article-list');
104	  var emptyTip = document.getElementById('empty-tip');
105	  var listNotice = document.getElementById('list-notice');
106	  var articles = [];
107	  // 首次列表读取是否已结束（成功或失败）。结果到达前用户保存的草稿绝不能
108	  // 被随后到达的旧快照覆盖；失败时这些已保存卡片也要继续保留。
109	  var listLoaded = false;
110	  // 首次列表读取失败的具体原因；空字符串表示当前没有失败。
111	  var listError = '';
112	  var saving = false;
113	  // null = 新建草稿模式；对象 = 正在编辑的服务端版本 {id,title,summary,body,version}
114	  var editing = null;
115	  // 冲突对照区当前的操作按钮，读取最新内容期间需暂时禁用
116	  var conflictActionButtons = [];
117	
118	  function setStatus(text, kind) {
119	    statusEl.textContent = text || '';
120	    statusEl.className = 'status' + (kind ? ' ' + kind : '');
121	  }
122	  function setEmpty(text, kind) {
123	    emptyTip.textContent = text || '';
124	    emptyTip.className = 'empty' + (kind ? ' ' + kind : '');
125	    emptyTip.hidden = !text;
126	  }
127	  function hideConflict() {
128	    conflictBox.hidden = true;
129	    conflictBox.textContent = '';
130	    conflictActionButtons = [];
131	  }
132	  function setConflictActionsDisabled(disabled) {
133	    conflictActionButtons.forEach(function (btn) { btn.disabled = disabled; });
134	  }
135	  function formatTime(iso) {
136	    var d = new Date(iso);
137	    return isNaN(d.getTime()) ? String(iso) : d.toLocaleString();
138	  }
139	  function render() {
140	    var sorted = articles.slice().sort(function (a, b) {
141	      var ta = a && a.createdAt ? String(a.createdAt) : '';
142	      var tb = b && b.createdAt ? String(b.createdAt) : '';
143	      if (ta !== tb) return ta < tb ? 1 : -1;
144	      return 0;
145	    });
146	    listEl.textContent = '';
147	    sorted.forEach(function (article) {
148	      var isEditing = editing && editing.id === article.id;
149	      var card = document.createElement('article');
150	      card.className = 'draft' + (isEditing ? ' editing' : '');
151	      var h = document.createElement('h3');
152	      h.textContent = article.title == null ? '' : String(article.title);
153	      if (isEditing) {
154	        var tag = document.createElement('span');
155	        tag.className = 'editing-tag';
156	        tag.textContent = '编辑中';
157	        h.appendChild(tag);
158	      }
159	      var meta = document.createElement('p');
160	      meta.className = 'meta';
161	      meta.textContent = '创建时间：' + formatTime(article.createdAt);
162	      var summary = document.createElement('p');
163	      summary.className = 'summary';
164	      var summaryText = article.summary == null ? '' : String(article.summary);
165	      summary.textContent = summaryText;
166	      card.appendChild(h);
167	      card.appendChild(meta);
168	      if (summaryText) card.appendChild(summary);
169	      var actions = document.createElement('p');
170	      actions.className = 'actions';
171	      var editBtn = document.createElement('button');
172	      editBtn.type = 'button';
173	      editBtn.className = 'secondary';
174	      editBtn.textContent = isEditing ? '正在编辑' : '编辑';
175	      editBtn.disabled = !!isEditing;
176	      editBtn.addEventListener('click', function () { startEdit(article.id); });
177	      actions.appendChild(editBtn);
178	      card.appendChild(actions);
179	      var li = document.createElement('li');
180	      li.appendChild(card);
181	      listEl.appendChild(li);
182	    });
183	    renderListChrome(sorted.length);
184	  }
185	
186	  function setNotice(text) {
187	    listNotice.textContent = text || '';
188	    listNotice.hidden = !text;
189	  }
190	
191	  // 列表区在“加载中 / 已取得完整列表 / 加载失败”三种状态下分别该显示什么。
192	  // 失败时绝不说成“还没有保存的草稿”：有本页面已保存的卡片就说明列表可能
193	  // 不完整、保存成功的草稿仍然保留；一张卡片都没有时也只显示真实失败原因。
194	  function renderListChrome(count) {
195	    listEl.setAttribute('aria-busy', listLoaded ? 'false' : 'true');
196	    if (listError) {
197	      setEmpty('');
198	      setNotice('草稿列表加载失败，完整列表尚未取得：' + listError
199	        + (count > 0 ? '。以下是本页面已经保存成功的草稿，仍然保留并可正常打开编辑。' : ''));
200	    } else if (!listLoaded) {
201	      setNotice('');
202	      setEmpty(count === 0 ? '草稿加载中…' : '');
203	    } else {
204	      setNotice('');
205	      setEmpty(count === 0 ? '还没有保存的草稿。' : '');
206	    }
207	  }
208	
209	  function versionNumberOf(article) {
210	    var v = article && article.version;
211	    return typeof v === 'number' && isFinite(v) ? v : 0;
212	  }
213	
214	  // 首次列表结果与本页面状态合并，而不是整体替换：
215	  // - 本页面已保存成功的文章必须保留；标题相同但标识不同的文章仍是两条
216	  //   记录，结果带回的其他文章也一并并入；
217	  // - 同一标识只保留一条：迟到的初始结果是页面上最旧的一份快照，同 id 时
218	  //   只有版本不旧于本地已知版本的数据才能覆盖，列表不能退回旧标题、摘要
219	  //   或版本（版本缺失按 0 处理，兼容旧数据）；
220	  // - 结果按创建时间倒序排列仍由 render 处理。
221	  // 合并只影响列表数据，绝不触碰表单输入、编辑对象与已取得的版本基准。
222	  function mergeInitialList(incoming) {
223	    var merged = articles.slice();
224	    var indexById = Object.create(null);
225	    merged.forEach(function (article, i) { indexById[String(article.id)] = i; });
226	    incoming.forEach(function (incomingArticle) {
227	      if (!incomingArticle || incomingArticle.id == null) return;
228	      var key = String(incomingArticle.id);
229	      var localIndex = Object.prototype.hasOwnProperty.call(indexById, key)
230	        ? indexById[key] : -1;
231	      if (localIndex < 0) {
232	        indexById[key] = merged.length;
233	        merged.push(incomingArticle);
234	        return;
235	      }
236	      if (versionNumberOf(incomingArticle) < versionNumberOf(merged[localIndex])) {
237	        return; // 迟到结果里的旧版本：保留本地已有的较新已保存内容
238	      }
239	      merged[localIndex] = incomingArticle;
240	    });
241	    articles = merged;
242	  }
243	
244	  function load() {
245	    return fetch('/api/articles', { headers: { accept: 'application/json' } })
246	      .then(function (r) {
247	        if (!r.ok) {
248	          return r.json().catch(function () { return null; }).then(function (data) {
249	            throw new Error(data && data.error ? data.error : ('HTTP ' + r.status));
250	          });
251	        }
252	        return r.json();
253	      })
254	      .then(function (data) {
255	        var incoming = data && Array.isArray(data.articles) ? data.articles : [];
256	        mergeInitialList(incoming);
257	        listError = '';
258	        listLoaded = true;
259	        render();
260	      })
261	      .catch(function (err) {
262	        // 首次列表读取失败：保留本页面已成功保存并显示的草稿，绝不用空
263	        // 结果替换列表，也不把“列表加载失败”说成保存失败或“没有草稿”。
264	        listError = err && err.message ? err.message : String(err);
265	        listLoaded = true;
266	        render();
267	      });
268	  }
269	
270	  function setSaving(on, label) {
271	    saving = on;
272	    saveBtn.disabled = on;
273	    saveBtn.textContent = label || (editing ? '保存修改' : '保存草稿');
274	    cancelBtn.disabled = on;
275	  }
276	
277	  function enterCreateMode(message, kind) {
278	    editing = null;
279	    form.reset();
280	    form.classList.remove('editing');
281	    editBanner.hidden = true;
282	    editBanner.textContent = '';
283	    hideConflict();
284	    cancelBtn.hidden = true;
285	    saveBtn.textContent = '保存草稿';
286	    setStatus(message || '', kind || '');
287	    render();
288	  }
289	
290	  function renderEditBanner(article) {
291	    editBanner.textContent = '';
292	    var line1 = document.createElement('div');
293	    line1.textContent = '正在编辑草稿：';
294	    var code = document.createElement('code');
295	    code.textContent = String(article.title);
296	    line1.appendChild(code);
297	    var line2 = document.createElement('div');
298	    line2.className = 'meta';
299	    line2.textContent = '创建时间：' + formatTime(article.createdAt) + ' · 标识：' + String(article.id);
300	    editBanner.appendChild(line1);
301	    editBanner.appendChild(line2);
302	  }
303	
304	  function applyEditingState(article) {
305	    editing = {
306	      id: article.id,
307	      title: article.title,
308	      summary: article.summary,
309	      body: article.body,
310	      version: article.version
311	    };
312	    // 列表同步为本次载入的已保存内容，使该草稿的标题、摘要与“编辑中”标识
313	    // 与载入结果一致（载入的可能比列表缓存更新）。
314	    var idx = -1;
315	    for (var i = 0; i < articles.length; i++) {
316	      if (articles[i] && articles[i].id === article.id) { idx = i; break; }
317	    }
318	    if (idx >= 0) articles[idx] = article; else articles.push(article);
319	    titleInput.value = article.title == null ? '' : String(article.title);
320	    summaryInput.value = article.summary == null ? '' : String(article.summary);
321	    bodyInput.value = article.body == null ? '' : String(article.body);
322	    form.classList.add('editing');
323	    renderEditBanner(article);
324	    editBanner.hidden = false;
325	    cancelBtn.hidden = false;
326	    saveBtn.textContent = '保存修改';
327	    hideConflict();
328	    setStatus('已载入该草稿当前保存的内容，可以开始修改。', null);
329	    render();
330	    titleInput.focus();
331	  }
332	
333	  function isDirty() {
334	    if (!editing) {
335	      return titleInput.value !== '' || summaryInput.value !== '' || bodyInput.value !== '';
336	    }
337	    return titleInput.value !== editing.title
338	      || summaryInput.value !== editing.summary
339	      || bodyInput.value !== editing.body;
340	  }
341	
342	  function formSnapshot() {
343	    return {
344	      title: titleInput.value,
345	      summary: summaryInput.value,
346	      body: bodyInput.value
347	    };
348	  }
349	
350	  // 通过单篇接口读取草稿当前已保存的完整内容（含正文与 version），
351	  // 绝不使用列表里的摘要充当正文。
352	  function fetchArticle(id) {
353	    return fetch('/api/articles/' + encodeURIComponent(id), { headers: { accept: 'application/json' } })
354	      .then(function (r) {
355	        return r.json().catch(function () { return null; }).then(function (data) {
356	          if (!r.ok || !data || !data.article) {
357	            throw new Error(data && data.error ? data.error : ('HTTP ' + r.status));
358	          }
359	          return data.article;
360	        });
361	      });
362	  }
363	
364	  // 读取成功后按开始读取时的快照决定载入方式：三个字段均未变（含改动后
365	  // 又恢复原值）直接载入；任一字段不同则先说明载入将丢弃等待期间的新修改，
366	  // 由用户明确选择。选择保留时全部输入、原编辑对象与原版本基准都保持原状，
367	  // 当前输入也不会被当作目标文章的修改。
368	  function loadFetchedArticle(snapshot, article, confirmMessage, keepMessage) {
369	    if (titleInput.value === snapshot.title
370	      && summaryInput.value === snapshot.summary
371	      && bodyInput.value === snapshot.body) {
372	      applyEditingState(article);
373	      return;
374	    }
375	    if (window.confirm(confirmMessage)) {
376	      applyEditingState(article);
377	    } else {
378	      setStatus(keepMessage, null);
379	    }
380	  }
381	
382	  function startEdit(id) {
383	    if (saving) return;
384	    if (isDirty() && !window.confirm('当前表单有未保存的修改，打开另一篇草稿将放弃这些输入。确定继续吗？')) {
385	      return;
386	    }
387	    // 记录开始读取时的表单快照。读取期间表单仍可继续输入，
388	    // 成功返回时据此判断是否有等待期间的新修改需要用户明确取舍。
389	    var snapshot = formSnapshot();
390	    setSaving(true, '读取中…');
391	    setStatus('正在读取草稿内容…', null);
392	    fetchArticle(id)
393	      .then(function (article) {
394	        setSaving(false);
395	        loadFetchedArticle(snapshot, article,
396	          '目标草稿已读取完成，但等待期间你又修改了标题、摘要或正文。'
397	          + '打开目标草稿将放弃这些新修改。\\n\\n'
398	          + '点击“确定”放弃新修改并打开目标草稿；点击“取消”保留当前输入，继续原来的操作。',
399	          '已保留当前输入，未打开目标草稿。');
400	      })
401	      .catch(function (err) {
402	        setSaving(false);
403	        saveBtn.textContent = editing ? '保存修改' : '保存草稿';
404	        setStatus('打开草稿失败：' + (err && err.message ? err.message : err) + '，可稍后重试。', 'err');
405	      });
406	  }
407	
408	  // 冲突后点击“放弃当前输入并载入最新内容”：绝不能直接使用冲突响应里
409	  // 带回的内容——那之后其他页面可能又保存过，旧对照已过时。始终重新通过
410	  // 单篇接口读取发生冲突的同一篇草稿在本次读取时实际保存的版本，读取成功
411	  // 后才以其进入编辑状态。该操作只读取，不保存、删除或新建任何记录。
412	  function reloadLatestSaved() {
413	    if (saving || !editing) return;
414	    var id = editing.id;
415	    // 不提前清空表单：读取期间标题、摘要和正文仍可继续输入。
416	    var snapshot = formSnapshot();
417	    setSaving(true, '读取中…');
418	    setStatus('正在读取该草稿最新已保存的内容…', null);
419	    setConflictActionsDisabled(true);
420	    fetchArticle(id)
421	      .then(function (article) {
422	        setSaving(false);
423	        setConflictActionsDisabled(false);
424	        loadFetchedArticle(snapshot, article,
425	          '最新内容已读取完成，但等待期间你又修改了标题、摘要或正文。'
426	          + '载入最新内容将放弃这些新修改。\\n\\n'
