834	function readBody(req: IncomingMessage): Promise<string> {
835	  return new Promise((resolve, reject) => {
836	    const chunks: Buffer[] = [];
837	    let size = 0;
838	    let tooLarge = false;
839	    let settled = false;
840	    // A declared Content-Length already tells us the request will exceed the
841	    // limit, but we must still consume the whole request before responding;
842	    // skip buffering from the start to bound memory use while draining.
843	    const declaredLength = Number(req.headers['content-length']);
844	    if (Number.isFinite(declaredLength) && declaredLength > MAX_BODY_BYTES) {
845	      tooLarge = true;
846	    }
847	    req.on('data', (chunk: unknown) => {
848	      if (settled) return;
849	      const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk));
850	      if (tooLarge) return; // draining the remainder; nothing left to buffer
851	      size += buf.length;
852	      if (size > MAX_BODY_BYTES) {
853	        // Keep reading (and discarding) the rest of the request instead of
854	        // calling req.destroy(): destroying the socket resets the connection
855	        // while the client is still sending, so it would never receive the
856	        // 400 response (only a network failure). The full request is drained,
857	        // then the rejection below produces a complete, readable response.
858	        tooLarge = true;
859	        chunks.length = 0;
860	        return;
861	      }
862	      chunks.push(buf);
863	    });
864	    req.on('end', () => {
865	      if (settled) return;
866	      settled = true;
867	      if (tooLarge) {
868	        reject(new HttpError(400, `request body exceeds the allowed size of ${MAX_BODY_BYTES} bytes`));
869	        return;
870	      }
871	      resolve(Buffer.concat(chunks).toString('utf8'));
872	    });
873	    req.on('error', (error: Error) => {
874	      if (settled) return;
875	      settled = true;
876	      reject(new HttpError(400, `could not read request body: ${error.message}`));
877	    });
878	    req.on('aborted', () => {
879	      if (settled) return;
880	      settled = true;
881	      reject(new HttpError(400, 'request body was not fully received'));
882	    });
883	  });
884	}
